import{_ as t,o as a,c as o,ah as s}from"./chunks/framework.BsNNkeaH.js";const f=JSON.parse('{"title":"Moving to a license","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/admission/ecoles/passage-licence.md","filePath":"src/en/admission/ecoles/passage-licence.md"}'),i={name:"en/admission/ecoles/passage-licence.md"};function r(l,e,n,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="moving-to-a-license" tabindex="-1">Moving to a license <a class="header-anchor" href="#moving-to-a-license" aria-label="Permalink to &quot;Moving to a license&quot;">​</a></h1><p>Once you&#39;re convinced by the free tier or the full-feature demo, moving to a paid license isn&#39;t something you do alone online: it&#39;s a step <strong>supported by edPage&#39;s sales team</strong>, who discuss your actual needs with you before setting up the license that fits your school.</p><h2 id="how-the-purchase-works" tabindex="-1">How the purchase works <a class="header-anchor" href="#how-the-purchase-works" aria-label="Permalink to &quot;How the purchase works&quot;">​</a></h2><ol><li>You reach out to the edPage team (or they reach out to you, typically during or at the end of your full-feature demo).</li><li>Together, you define which modules your school needs and which hosting formula suits you.</li><li>The edPage team sets up the license for your school from its internal panel.</li><li>Your space immediately reflects the licensed modules — no need to wait for an update or a reinstall.</li></ol><p>There&#39;s no self-service online payment for buying a license: that&#39;s deliberate, so that each license actually matches what your school needs rather than a fixed offer picked alone in a form.</p><h2 id="modules-available-a-la-carte" tabindex="-1">Modules available à la carte <a class="header-anchor" href="#modules-available-a-la-carte" aria-label="Permalink to &quot;Modules available à la carte&quot;">​</a></h2><p>ERA is licensed module by module rather than as one block: you choose the ones that match your needs, or the full offer if you&#39;d rather cover everything from the start. The modules cover, among others:</p><ul><li>school structure and admissions (beyond the public application form already included for free);</li><li>academic life (classes, timetables, assessments, attendance, boarding, health...);</li><li>finances (tuition fees, payments, expenses);</li><li>family relations (parent portal, student portal);</li><li>the reporting dashboard.</li></ul><p>The exact scope of each module and its price are communicated by the edPage team when it&#39;s set up — they can evolve and aren&#39;t meant to be fixed in this guide.</p><h2 id="the-two-hosting-formulas" tabindex="-1">The two hosting formulas <a class="header-anchor" href="#the-two-hosting-formulas" aria-label="Permalink to &quot;The two hosting formulas&quot;">​</a></h2><p>Once the license is purchased, your school chooses between two hosting formulas. The choice isn&#39;t trivial: it determines who actually manages your server day to day.</p><h3 id="self-hosted-default" tabindex="-1">Self-hosted (default) <a class="header-anchor" href="#self-hosted-default" aria-label="Permalink to &quot;Self-hosted (default)&quot;">​</a></h3><p>This is the default formula: your school hosts its own installation of ERA, on its own server. The edPage team supports you through the initial setup (transferring the admission data you&#39;ve already entered, activating the license on your server), but day-to-day hosting — uptime, backups, technical maintenance — is then up to your school or its technical provider.</p><p>This formula suits schools that already have (or want) control over their own infrastructure.</p><h3 id="managed-paid" tabindex="-1">Managed (paid) <a class="header-anchor" href="#managed-paid" aria-label="Permalink to &quot;Managed (paid)&quot;">​</a></h3><p>With this formula, edPage keeps hosting your school on its infrastructure — exactly as during your free signup and demo, except that read-write access stays open continuously, with no time limit and no read-only freeze. This hosting service is billed on top of the license itself.</p><p>This formula suits schools that would rather not manage a server at all and leave that responsibility to edPage.</p><h3 id="what-actually-changes-for-you" tabindex="-1">What actually changes for you <a class="header-anchor" href="#what-actually-changes-for-you" aria-label="Permalink to &quot;What actually changes for you&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Self-hosted</th><th>Managed</th></tr></thead><tbody><tr><td>Who hosts the server</td><td>Your school</td><td>edPage</td></tr><tr><td>Hosting cost</td><td>None (beyond your own infrastructure)</td><td>Billed on top of the license</td></tr><tr><td>Initial setup</td><td>Supported by edPage (data transfer, activation)</td><td>Fully handled by edPage</td></tr><tr><td>Day-to-day access</td><td>Identical — licensed modules work the same either way</td><td>Identical — licensed modules work the same either way</td></tr></tbody></table><p>In both cases, the modules you&#39;ve licensed work the same way for your users (admin, teachers, front office...) — only the question of &quot;who takes care of the server&quot; changes.</p>',20)])])}const m=t(i,[["render",r]]);export{f as __pageData,m as default};
